21	// Runner drives one target through concurrency levels of one workload. The
22	// caller owns the sweep loop: it calls RunLevel once per level, so level
23	// lifecycle (start/end, the returned LevelResult) is the caller's to observe —
24	// the engine only reports per-operation samples, via the optional Sink.
25	type Runner struct {
26		target Target
27		w      Workload
28		creds  credentialProvider
29		ep     *endpoint
30		httpc  *http.Client
31		sink   Sink
32	
33		tokenExp   time.Time // zero: not a JWT, the server decides
34		levelsLeft int       // levels not yet started
35	}
36	
37	// NewRunner resolves a target (credentials + endpoint; for entiredb this
38	// probes the cluster) and validates the workload against it. sink may be nil.
39	func NewRunner(ctx context.Context, t Target, w Workload, sink Sink) (*Runner, error) {
40		if err := w.Validate(); err != nil {
41			return nil, err
42		}
43		if len(t.Repos) == 0 {
44			return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
45		}
46		if w.Strategy == "repo" && len(t.Repos) < 2 {
47			return nil, errors.New("strategy=repo needs >= 2 repos")
48		}
49		if t.Secret == "" {
50			return nil, errors.New("no credential secret provided")
51		}
52		httpc := newHTTPClient(t.Insecure, slices.Max(w.Concurrency)+8)
53	
54		var (
55			creds credentialProvider
56			ep    *endpoint
57			err   error
58		)
59		if t.TokenURL != "" || t.Jurisdiction != "" {
60			// Go forwards Authorization on same-domain redirects, which would
61			// carry the account access token past pinReplicas on any request.
62			// The discovery probe vets its own redirect.
63			httpc = refuseRedirects(httpc)
64			creds, ep, err = setupEntiredb(ctx, t, httpc)
65		} else {
66			creds, ep, err = setupGeneric(t)
67		}
68		if err != nil {
69			httpc.CloseIdleConnections() // drop the discovery probe's pool
70			return nil, err
71		}
72		r := &Runner{target: t, w: w, creds: creds, ep: ep, httpc: httpc, sink: sink, levelsLeft: len(w.Concurrency)}
73		if t.TokenURL != "" || t.Jurisdiction != "" {
74			// Only Entire's account token bounds the run. After discovery, so
75			// its time counts against the token.
76			r.tokenExp, _ = jwtExpiry(t.Secret)
77			if err := r.tokenCovers(time.Now()); err != nil {
78				r.Close()
79				return nil, err
80			}
81		}
82		return r, nil
83	}
84	
85	// Label is the resolved endpoint label (the remote base URL), for banners and
86	// results.
87	func (r *Runner) Label() string { return r.ep.label }
88	
89	// Nodes is how many push destinations the endpoint fans out across (1 for any
90	// plain forge; the discovered replica count for entiredb).
91	func (r *Runner) Nodes() int { return len(r.ep.nodes) }
92	
93	// ObjectFormat is the resolved wire object format ("sha1" or "sha256").
94	func (r *Runner) ObjectFormat() string { return string(r.ep.objFmt) }
95	
96	// Close releases the runner's resources once its run is over: it drops idle
97	// keep-alive connections and severs the runner's reference to the credential
98	// provider, so the credential (a PAT, or an Entire subject/access token) held
99	// for the run becomes eligible for garbage collection instead of living on in a
100	// finished run kept resident in memory. Go strings can't be wiped in place, so
101	// dropping the reference is the strongest release available.
102	func (r *Runner) Close() {
103		// Stop any background token refresh before dropping the reference, or a
104		// detached exchange could keep running (and holding the token) after the run.
105		if c, ok := r.creds.(credentialCloser); ok {
106			c.close()
107		}
108		if r.httpc != nil {
109			r.httpc.CloseIdleConnections()
110		}
111		r.creds = nil
112		r.target.Secret = "" // drop the runner's own copy of the token
113	}
114	
115	// credentialCloser is an optional credentialProvider capability: release any
116	// background machinery and the credentials it holds.
117	type credentialCloser interface{ close() }
118	
119	// StartBarrier synchronizes the start of one concurrency level across several
120	// runners: each Arrives once its agents are built, and the coordinator
121	// releases them together, so target-dependent setup time can't skew the
122	// measured windows of a comparison run. It tolerates a runner that fails
123	// before it is ready — that runner still Arrives, so Await can't hang. A nil
124	// barrier means "run alone, no synchronization" (the CLI's single-target path).
125	type StartBarrier struct {
126		arrived chan struct{}
127		release chan struct{}
128		n       int
129		firedAt time.Time // set before release closes; the shared start instant
130	}
131	
132	// NewStartBarrier makes a barrier expecting n participants.
133	func NewStartBarrier(n int) *StartBarrier {
134		return &StartBarrier{arrived: make(chan struct{}, n), release: make(chan struct{}), n: n}
135	}
136	
137	// Arrive reports that this participant has finished preparing (or has given up
138	// and won't Hold). The buffered channel makes it non-blocking.
139	func (b *StartBarrier) Arrive() { b.arrived <- struct{}{} }
140	
141	// Hold blocks until the coordinator fires the shared start signal.
142	func (b *StartBarrier) Hold() { <-b.release }
143	
144	// Await blocks until every participant has Arrived.
145	func (b *StartBarrier) Await() {
146		for i := 0; i < b.n; i++ {
147			<-b.arrived
148		}
149	}
150	
151	// Fire releases every held participant to begin its timed window together. It
152	// stamps firedAt before closing release, so every participant and the
153	// coordinator share one start instant (via FiredAt) rather than each reading
154	// its own time.Now after being scheduled — which would skew the sample clock
155	// against the window/dt_ms timestamps. The close is a happens-before edge, so
156	// the write is visible to every Hold() that returns.
157	func (b *StartBarrier) Fire() {
158		b.firedAt = time.Now()
159		close(b.release)
160	}
161	
162	// FiredAt is the shared start instant, valid after Fire (for the coordinator) or
163	// after Hold returns (for a participant).
164	func (b *StartBarrier) FiredAt() time.Time { return b.firedAt }
165	
166	// RunLevel runs a single concurrency level: build c agents, wait at the
167	// barrier so all targets start together, run for warmup+duration, then fold
168	// the samples into one result. It blocks for the full level window (or until
169	// ctx is cancelled). barrier may be nil to run without synchronization.
170	func (r *Runner) RunLevel(ctx context.Context, c int, barrier *StartBarrier) (LevelResult, error) {
171		var clone *cloneConfig
172		var sess *sessionConfig
173		switch r.w.Strategy {
174		case "clone":
175			clone = &cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef}
176		case "session":
177			sess = &sessionConfig{
178				cloneConfig: cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef},
179				commits:     r.w.SessionCommits,
180			}
181		}
182		agents := make([]*agent, c)
183		for i := range c {
184			repoPath := r.target.Repos[0]
185			if r.w.Strategy == "repo" {
186				repoPath = r.target.Repos[i%len(r.target.Repos)]
187			}
188			node := r.ep.nodes[i%len(r.ep.nodes)]
189			ref := DestRef(r.w.Namespace(), r.w.BranchPrefix, r.w.RunID, c, i)
190			a, err := newAgent(i, repoPath, node, ref, r.ep.objFmt, &r.w.Commit, r.creds, r.httpc, clone, sess, r.sink)
191			if err != nil {
192				if barrier != nil {
193					barrier.Arrive() // don't leave the coordinator's Await hanging
194				}
195				return LevelResult{}, fmt.Errorf("new agent %d: %w", i, err)
196			}
197			agents[i] = a
198		}
199	
200		// Agents are built; wait for every target before starting the clock, so the
201		// measured window begins at the same instant on each and the comparison is
202		// fair regardless of per-target setup time.
203		if barrier != nil {
204			barrier.Arrive()
205			barrier.Hold()
206		}
207	
208		total := r.w.Warmup + r.w.Duration
209		// Origin the sample clock AND the context deadline on the same instant — the
210		// barrier's shared fire time when there is one. Using FiredAt for the offset
211		// origin but a scheduled-now timeout for the deadline let a target released
212		// late run a full `total` from its late start, recording samples past the
213		// shared window end that summarize then miscounts against the fixed duration.
214		// Deriving the deadline from FiredAt()+total stops every target together.
215		// Single-target CLI runs have no barrier and just start now.
216		start := time.Now()
217		if barrier != nil {
218			start = barrier.FiredAt()
219		}
220		// Recheck at the window: discovery, agent setup, the barrier and the
221		// previous level's cleanup all spent token lifetime.
222		if err := r.tokenCovers(start); err != nil {
223			return LevelResult{}, err
224		}
225		r.levelsLeft = max(r.levelsLeft-1, 0)
226		lvlCtx, cancel := context.WithDeadline(ctx, start.Add(total))
227		defer cancel()
228		var wg sync.WaitGroup
229		for _, a := range agents {
230			wg.Add(1)
231			go func(a *agent) {
232				defer wg.Done()
233				a.run(lvlCtx, start)
234			}(a)
235		}
236		wg.Wait()
237	
238		var all []Sample
239		for _, a := range agents {
240			all = append(all, a.samples...)
241		}
242		reposUsed := 1
243		if r.w.Strategy == "repo" {
244			reposUsed = min(c, len(r.target.Repos))
245		}
246		return summarize(all, c, r.w.Strategy, reposUsed, len(r.ep.nodes), r.w.Warmup, r.w.Duration, r.w.CommitDesc()), nil
247	}
248	
249	func setupGeneric(t Target) (credentialProvider, *endpoint, error) {
250		if t.Remote == "" {
251			return nil, nil, errors.New("-remote required (e.g. https://gitlab.com); for entiredb also pass -token-url and -jurisdiction")
252		}
253		if IsGitHubDotCom(t.Remote) && t.ObjectFmt == "sha256" {
254			return nil, nil, errors.New("github.com is sha1; drop -object-format sha256")
255		}
256		objFmt, err := parseObjectFormat(t.ObjectFmt)
257		if err != nil {
258			return nil, nil, err
259		}
260		user := t.User
261		if user == "" {
262			user = "x-access-token" // token forges ignore the username; the token is the password
263		}
264		return staticCreds{username: user, password: t.Secret}, newGenericEndpoint(t.Remote, objFmt), nil
265	}
266	
267	// tokenCovers refuses to start work the account access token cannot
268	// cover: nothing refreshes it, so a level that outlives it would report
269	// authentication failures as throughput. It needs every level not yet
270	// started, plus session ref cleanup after each window and clock skew,
271	// measured from now. A secret that is not a JWT with exp passes.
272	func (r *Runner) tokenCovers(now time.Time) error {
273		if r.tokenExp.IsZero() {
274			return nil
275		}
276		levels := max(r.levelsLeft, 1)
277		var cleanup time.Duration
278		if r.w.Strategy == "session" {
279			cleanup = sessionCleanupTimeout
280		}
281		need := time.Duration(levels)*(r.w.Warmup+r.w.Duration+cleanup) + tokenSkew
282		if left := r.tokenExp.Sub(now); left < need {
283			return fmt.Errorf("token expires in %s but %d remaining levels need %s (warmup %s + duration %s + cleanup %s each, + %s skew); mint a fresher token or shorten the run",
284				max(left, 0).Round(time.Second), levels, need, r.w.Warmup, r.w.Duration, cleanup, tokenSkew)
285		}
286		return nil
287	}
288	
289	// tokenSkew absorbs clock drift against the issuer.
290	const tokenSkew = 30 * time.Second
291	
292	// jwtExpiry reads exp from an unverified JWT payload.
293	func jwtExpiry(token string) (time.Time, bool) {
294		parts := strings.Split(token, ".")
295		if len(parts) != 3 {
296			return time.Time{}, false
297		}
298		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
299		if err != nil {
300			return time.Time{}, false
301		}
302		var c struct {
303			Exp int64 `json:"exp"`
304		}
305		if json.Unmarshal(payload, &c) != nil || c.Exp == 0 {
306			return time.Time{}, false
307		}
308		return time.Unix(c.Exp, 0), true
309	}
310	
311	// refuseRedirects returns a copy of c (same transport and pool) that fails
312	// every redirect instead of following it.
313	func refuseRedirects(c *http.Client) *http.Client {
314		out := *c
315		out.CheckRedirect = func(*http.Request, []*http.Request) error {
316			return errors.New("entiredb request attempted a redirect; refusing to forward the credential")
317		}
318		return &out
319	}
320	
321	func setupEntiredb(ctx context.Context, t Target, httpc *http.Client) (credentialProvider, *endpoint, error) {
322		var missing []string
323		if t.Remote == "" {
324			missing = append(missing, "-remote (cluster base URL)")
325		}
326		if t.TokenURL == "" {
327			missing = append(missing, "-token-url")
328		}
329		if t.Jurisdiction == "" {
330			missing = append(missing, "-jurisdiction")
331		}
332		if len(missing) > 0 {
333			return nil, nil, fmt.Errorf("entire target (selected by -token-url/-jurisdiction) also needs: %s", strings.Join(missing, ", "))
334		}
335		// The subject token is the account access token; entiredb authorizes each
336		// push live on its subject, so it is presented as-is (ADR 20260729).
337		// Entire ignores the username.
338		creds := staticCreds{username: "token", password: t.Secret}
339		ep, err := newEntireEndpoint(ctx, t.Remote, t.ObjectFmt, t.Repos[0], creds, httpc)
340		if err != nil {
341			return nil, nil, err
342		}
343		return creds, ep, nil
344	}
345	
346	func parseObjectFormat(s string) (formatcfg.ObjectFormat, error) {
347		switch s {
348		case "sha256":
349			return formatcfg.SHA256, nil
350		case "sha1", "auto", "": // generic doesn't probe; auto degrades to sha1
351			return formatcfg.SHA1, nil
352		default:
353			return "", fmt.Errorf("invalid -object-format %q (sha1|sha256|auto)", s)
354		}
355	}
356	
357	func newHTTPClient(insecure bool, maxConns int) *http.Client {
358		tr := &http.Transport{
359			Proxy:               http.ProxyFromEnvironment,
360			MaxIdleConns:        maxConns * 2,
361			MaxIdleConnsPerHost: maxConns,
362			MaxConnsPerHost:     0, // unbounded: don't queue pushes behind a conn cap
363			IdleConnTimeout:     90 * time.Second,
364		}
365		if insecure {
366			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // load-test opt-in
367		}
368		// Client.Timeout must stay zero: with a wrapped RoundTripper a nonzero
369		// value falls off net/http's known-transport fast path and spawns a
370		// cancellation goroutine per request, skewing the very operations
371		// forgemark measures. uaTransport enforces the timeout instead.
372		return &http.Client{Transport: &uaTransport{base: tr, timeout: 120 * time.Second}}
373	}
374	
375	// uaToken identifies forgemark in User-Agent headers. Binaries built from a
376	// git checkout carry the commit via Go's embedded VCS info, so server logs can
377	// tie traffic to an exact revision — with "-dirty" when the tree had
378	// uncommitted changes; otherwise (go test, -buildvcs=off) it's the bare name.
379	var uaToken = func() string {
380		bi, ok := debug.ReadBuildInfo()
381		if !ok {
382			return "forgemark"
383		}
384		var revision, dirty string
385		for _, s := range bi.Settings {
386			switch s.Key {
387			case "vcs.revision":
388				revision = s.Value
389				if len(revision) > 12 {
390					revision = revision[:12]
391				}
392			case "vcs.modified":
393				if s.Value == "true" {
394					dirty = "-dirty"
395				}
396			}
397		}
398		if revision == "" {
399			return "forgemark"
400		}
401		return "forgemark/" + revision + dirty
402	}()
403	
404	// uaTransport appends uaToken to every request's User-Agent so server logs can
405	// attribute load-test traffic. Appending keeps go-git's agent string first
406	// (servers may key protocol behavior on it), and tagging only the HTTP header
407	// leaves the git protocol's agent capability untouched — go-git's
408	// GO_GIT_USER_AGENT_EXTRA hook would land there too, where the embedded space
409	// reads as a bogus extra capability, and would leak into subprocess
410	// environments.
411	//
412	// It also imposes the request timeout as a context deadline (see
413	// newHTTPClient). Unlike Client.Timeout the budget is per attempt, not per
414	// redirect chain; forgemark's endpoints don't redirect, so that difference is
415	// theoretical.
416	type uaTransport struct {
417		base    *http.Transport
418		timeout time.Duration
419	}
420	
421	func (t *uaTransport) RoundTrip(req *http.Request) (*http.Response, error) {
422		// Per the RoundTripper contract, don't mutate the caller's request.
423		ctx, cancel := context.WithTimeout(req.Context(), t.timeout)
424		req = req.Clone(ctx)
425		if ua := req.Header.Get("User-Agent"); ua != "" {
426			req.Header.Set("User-Agent", ua+" "+uaToken)
427		} else {
428			req.Header.Set("User-Agent", uaToken)
429		}
430		resp, err := t.base.RoundTrip(req)
431		if err != nil {
432			cancel()
433			return nil, err
434		}
435		// Like Client.Timeout, the deadline covers reading the body; the timer is
436		// released when the caller closes it.
437		resp.Body = &cancelOnClose{ReadCloser: resp.Body, cancel: cancel}
438		return resp, nil
439	}
440	
441	// CloseIdleConnections forwards to the underlying transport; without it,
442	// http.Client.CloseIdleConnections (used by run cleanup) would be a no-op.
443	func (t *uaTransport) CloseIdleConnections() { t.base.CloseIdleConnections() }
444	
445	type cancelOnClose struct {
446		io.ReadCloser
447		cancel context.CancelFunc
448	}
449	
450	func (b *cancelOnClose) Close() error {
451		b.cancel()
452		return b.ReadCloser.Close()
453	}
