	c.OnSample(bench.Sample{Res: bench.OutcomeCAS})
	c.OnSample(bench.Sample{Dur: ms(5), Res: bench.OutcomeErr, Msg: "boom"})
	c.OnSample(bench.Sample{Op: bench.OpClone, Dur: ms(100), Res: bench.OutcomeOK})

